const page=await figma.getNodeByIdAsync('5:2');
await figma.setCurrentPageAsync(page);
const main=await figma.getNodeByIdAsync('8:13');
const setP=page.children.find(c=>c.name==='ProjectCard');
const setB=page.children.find(c=>c.name==='Button');
const setS=page.children.find(c=>c.name==='SocialButton');
const navSet=page.children.find(c=>c.name==='NavItem');
function hover(id){return [{trigger:{type:'ON_HOVER'},actions:[{type:'NODE',destinationId:id,navigation:'CHANGE_TO',transition:{type:'SMART_ANIMATE',easing:{type:'EASE_OUT'},duration:0.15},resetVideoPosition:false}]}];}
const log=[];
const proj=main.children.find(c=>c.name==='Projects');
const grid=proj.children.find(c=>c.name==='Project grid');
const hovers={};
for(const v of setP.children){ hovers[v.name]=v.id; }
grid.children.forEach((inst,i)=>{
  const target=hovers[i===0?'Photo=HTML, State=Hover':'Photo=CSS, State=Hover'];
  if(target) inst.reactions=hover(target);
  log.push(['card',i,'ok']);
});
// nav hover
for(const item of main.children.find(c=>c.name==='Header').children.find(c=>c.name==='Nav').children){
  const cur=[...item.reactions];
  if(!cur.some(r=>r.trigger.type==='ON_HOVER')) cur.push(...hover(navSet.children.find(v=>v.name==='State=Hover').id));
  item.reactions=cur;
}
// buttons & socials
for(const inst of main.findAll(n=>n.type==='INSTANCE')){
  const comp=inst.mainComponent; if(!comp) continue;
  const owner=comp.parent;
  if(!owner||owner.type!=='COMPONENT_SET') continue;
  if(owner===setB||owner===setS){
    const h=owner.children.find(v=>v.name===comp.name.replace('State=Default','State=Hover'));
    if(h){ inst.reactions=hover(h.id); log.push([inst.name,'hover']); }
