const page=await figma.getNodeByIdAsync('5:2');
await figma.setCurrentPageAsync(page);
const log=[];
function layoutSet(set,cols,padX,padY){
  if(!set||set.type!=='COMPONENT_SET'){log.push([set?set.name:'none','skip']);return;}
  const kids=[...set.children];
  let maxW=0,maxH=0;
  const cw=[],chh=[];
  kids.forEach((k,i)=>{ cw[i]=k.width; chh[i]=k.height; maxW=Math.max(maxW,k.width); maxH=Math.max(maxH,k.height);});
  kids.forEach((k,i)=>{
    const r=Math.floor(i/cols),c=i%cols;
    k.x=padX+c*(maxW+40);
    k.y=padY+r*(maxH+56);
  });
  set.resize(padX*2+cols*maxW+(cols-1)*40+0, padY*2+Math.ceil(kids.length/cols)*maxH+(Math.ceil(kids.length/cols)-1)*56);
  log.push([set.name,set.width,set.height,kids.map(k=>[k.name,k.x,k.y])]);
}
layoutSet(page.children.find(c=>c.name==='Button'),2,24,24);
layoutSet(page.children.find(c=>c.name==='NavItem'),3,24,24);
layoutSet(page.children.find(c=>c.name==='SocialButton'),3,24,24);
layoutSet(page.children.find(c=>c.name==='CompanyMark'),3,24,24);
layoutSet(page.children.find(c=>c.name==='TechLogo'),5,24,24);
layoutSet(page.children.find(c=>c.name==='ProjectCard'),2,24,24);
layoutSet(page.children.find(c=>c.name==='ExperienceItem'),1,24,24);
return log;

